/* 第 33 章 — 逆向自 R_33.EEX */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch33","num":33,"title":"第 33 章","desc":"第 33 章（原版剧本 R_33.EEX）","map":"assets/maps/map33.png","intro":{"title":"第 33 章","nodes":[{"type":"scene","bg":"default","name":"投降之议"},{"type":"say","who":"旁白","text":"成都皇宫"},{"type":"say","who":"糜照","text":"两万人马全军覆没，卫将军诸葛瞻父子、尚书郎黄崇、羽林右部督李球和尚书张遵等人全数战死。"},{"type":"say","who":"关彝","text":"邓艾大军已经突破绵竹关，现在距离成都应该已经不到一百里，请陛下早做决断。"},{"type":"say","who":"刘禅","text":"连卫将军都不行了？"},{"type":"say","who":"郤正","text":"卫将军真是误国！可怜了那两万将士的宝贵性命！"},{"type":"say","who":"谯周","text":"（黄崇和李球，你们两个人可是我益州人中的佼佼者，没想到就为了这样没意义的战争而丧命。）"},{"type":"say","who":"谯周","text":"（我发誓，绝对不会让益州人继续牺牲下去了。）"},{"type":"say","who":"刘禅","text":"成都还有多少兵马？有能力抵抗吗？"},{"type":"say","who":"谯周","text":"现在邓艾兵临成都的消息已经传开，人民震动，陷入一片混乱。"},{"type":"say","who":"谯周","text":"益州人大家扶老携幼，逃入深山或是沼泽地带，现在就算要禁止，恐怕也无法收到效果。"},{"type":"say","who":"刘禅","text":"这么说，已经没有人愿意为大汉卖命了？"},{"type":"say","who":"谯周","text":"正是如此。"},{"type":"say","who":"宗预","text":"我们大汉和东吴是兄弟之邦，不如向东顺水而下，投奔东吴。"},{"type":"say","who":"郤正","text":"微臣倒认为，南中地区尚有七郡，山险水恶，容易守备，不如投靠南中。"},{"type":"say","who":"谯周","text":"万万不可！"},{"type":"say","who":"谯周","text":"自古以来，从来没有寄住别国还能当皇帝的事情。如果投奔东吴，不免要当他们的臣属。"},{"type":"say","who":"谯周","text":"而且东吴和大汉的立国条件相同，大国并吞小国乃自然之趋势。"},{"type":"say","who":"谯周","text":"现在很明显看得出曹贼有能力并吞东吴，而东吴没有能力并吞曹贼。反正要低头称臣，与其要受两次侮辱，不如只受一次。"},{"type":"say","who":"谯周","text":"至于迁都南中，必须早早规划才能实现。现在大敌当前，小人们想什么，没人可以保证。"},{"type":"say","who":"谯周","text":"只怕陛下抬脚要走的那天，就可能发生巨变，怎么可以到南中呢？"},{"type":"say","who":"刘禅","text":"难道不能考虑一下迁都南中？"},{"type":"say","who":"谯周","text":"南中是遥远的蛮族地区，承平时代，既不缴纳田赋捐税，又不供应民夫差役，对国家毫无贡献，还不断反叛。"},{"type":"say","who":"谯周","text":"虽说丞相当时用军事力量压制成功，但如今迁都，对外要对抗强敌，对内要负担官员开支。"},{"type":"say","who":"谯周","text":"如此庞大的消耗数字，没有其他财源，只能依靠蛮族，蛮族必定造反。"},{"type":"say","who":"樊建","text":"问题是，如果邓艾不接受我们投降该怎么办？"},{"type":"say","who":"谯周","text":"东吴仍然存在，所以邓艾非接受我们投降不可，并且一定对陛下有盛大的礼遇。"},{"type":"say","who":"谯周","text":"陛下投降后，如果不肯封陛下采邑，臣愿前往洛阳，据理力争！"},{"type":"say","who":"刘禅","text":"朕只想问最后一次，光禄大夫认为我们还能抵抗吗？"},{"type":"say","who":"谯周","text":"不可能，也没有人有这样的意愿。"},{"type":"say","who":"宗预","text":"（不用想成是益州人的报复，都已经搞到兵临城下，城内也几乎没兵可用，还会有谁有作战意识呢？）"},{"type":"say","who":"黄皓","text":"（其实最不希望投降的就是我呀，你们有学问、有名声，在新主子那还可以被重用。）"},{"type":"say","who":"黄皓","text":"（我呢？除了会取悦圣上外，又能做什么？然而我出来反对投降，只会让情况更糟，实在令人感慨。）"},{"type":"say","who":"刘禅","text":"好吧，该做的也都做了，能做的也都做了。"},{"type":"say","who":"刘禅","text":"侍中！"},{"type":"say","who":"张绍","text":"微臣在！"},{"type":"say","who":"刘禅","text":"把朕的印信交到邓艾手上去。"},{"type":"say","who":"刘禅","text":"太仆！"},{"type":"say","who":"蒋显","text":"微臣在！"},{"type":"say","who":"刘禅","text":"命你带著诏书，叫大将军就近投降。"},{"type":"say","who":"刘谌","text":"父皇，难道您就这样投降？"},{"type":"say","who":"刘禅","text":"事到如今，又能做什么呢？"},{"type":"say","who":"刘谌","text":"您忘记先帝创业的艰苦？您忘记丞相守成的不易？我们大汉的江山岂能这样拱手让出？"},{"type":"say","who":"刘谌","text":"如果真到了穷途末路，就应该父子君臣，背城一战，同时以死殉国，到地下去见先帝。为什么要投降？"},{"type":"say","who":"刘禅","text":"够了！朕意已定…"},{"type":"say","who":"刘谌","text":"天啊！我大汉的江山啊…"},{"type":"say","who":"刘禅","text":"（你懂什么？朕已经是到了山穷水尽才会出此下策，有谁比朕更痛苦？你们可以轻松一死当忠臣，朕还得活著面对屈辱。）"},{"type":"say","who":"刘禅","text":"（父亲呀…您能够明白孩儿的痛苦吗？您能够原谅孩儿的作为吗？）北地王殉国昭烈帝祭庙"},{"type":"say","who":"刘谌","text":"先帝呀，孙儿我已经尽了全力，无奈父皇只愿听信小人谯周的妖言，坚持要将大汉江山拱手让人。"},{"type":"say","who":"刘谌","text":"现在孙儿只好以身殉国，我不会让自己的妻儿受辱，所以已经先杀了他们。"},{"type":"say","who":"刘谌","text":"虽然我对您充满敬仰，但我毕竟没有真的见过您。希望您不会觉得我配不上当您的孙子北地王刘谌在刘禅决议投降的当天，到刘备祭庙，哀哀痛哭，先杀了妻子之后，再挥刀自刎。邓艾受降雒城魏军营帐"},{"type":"say","who":"张绍","text":"大汉户口二十八万，人民九十四万，军队十万两千人，政府官员四万人，这些全都交给将军您了。"},{"type":"say","who":"张绍","text":"此外，这是我大汉皇帝的印信，也请您一并收下。"},{"type":"say","who":"张绍","text":"至于陛下本人则会亲自率领太子和文武百官来您大营请降。"},{"type":"say","who":"邓艾","text":"（终于到了这一天了，天下三分四十余年，想不到是由我邓艾来结束这样分裂的局面。）"},{"type":"say","who":"邓艾","text":"我这就马上出发前往成都，也请告诉蜀主，要他不用担心。"},{"type":"say","who":"邓艾","text":"我邓艾会接受他的投降，而且会约束手下不准劫掠人民。"},{"type":"say","who":"张绍","text":"如此，真是我大汉人民之福。"},{"type":"say","who":"张绍","text":"（唉…这种肮脏的工作也是得有人做，就让我这张家的不肖子来吧…）公元二六三年，邓艾抵达成都北郊，刘禅率领太子及亲族、文武官员共六十多人，双手捆绑背后，带著棺木前往迎接。邓艾解开他们捆绑，焚烧棺木，正式接受刘禅等人的投降。蜀汉自二二一年由先主刘备创立，到二六三年后主刘禅投降曹魏，建国共四十三年，至此灭亡。邓艾之后仿效邓禹当年行事，“承制”（代表皇帝）任命刘禅代理骠骑将军、太子奉车、诸王驸马都尉。邓艾并任命师纂兼任益州刺史，牵弘等人也被任命为各郡太守。黄皓的下场成都皇宫"},{"type":"say","who":"邓艾","text":"我发现你这家伙还挺有名的…"},{"type":"say","who":"黄皓","text":"能让征西将军大人知道小人，小人可是备感荣幸。"},{"type":"say","who":"邓艾","text":"我这辈子最讨厌两样东西…牛和太监…"},{"type":"say","who":"黄皓","text":"小人虽然是太监，但却是个善良又纯朴的小太监，饶了小人吧。"},{"type":"say","who":"邓艾","text":"哼！你祸国殃民，陷害忠良，搞得政治乌烟瘴气，人民怨声载道，要是杀了你，应该是大快人心吧。"},{"type":"say","who":"黄皓","text":"不要…求求您饶了小人吧……"},{"type":"say","who":"师纂","text":"其实征西将军您没必要对一个小人下这样的重手吧…"},{"type":"say","who":"师纂","text":"黄皓虽然结党营私，破坏纲纪，是蜀国灭亡的元凶之一。"},{"type":"say","who":"师纂","text":"但蜀主刘禅和其他大臣难道不需要负责？"},{"type":"say","who":"师纂","text":"黄皓不过是个小小中常侍，没有刘禅给予权柄，他可以这样公然干政？"},{"type":"say","who":"师纂","text":"如果不是大臣利欲薰心，黄皓纵有权力，也不过是个人单势孤的太监而已。"},{"type":"say","who":"邓艾","text":"你说得还挺有道理的，想不到几日不见，你的见识增长不少。"},{"type":"say","who":"邓艾","text":"蜀国内部早就有严重的不和谐情况发生，是这样的不和谐让我们有机可乘，黄皓只是那些真正罪魁祸首的代罪羔羊而已。"},{"type":"say","who":"师纂","text":"（嘿嘿，其实是我收了黄皓一堆银子，说出这些他教我的话而已。）"},{"type":"say","who":"邓艾","text":"黄皓，我这就把你流放南中，你一辈子也不许回到蜀地来，可以吗？"},{"type":"say","who":"黄皓","text":"感谢将军开恩，您真是明事理，难怪当初陛下会愿意向您投降…"},{"type":"say","who":"邓艾","text":"呵呵呵…是呀，若是那个钟士季，我就不保证他会做什么事。"},{"type":"say","who":"邓艾","text":"（是到了该写信给他的时候…）撤退之议姜维军营帐"},{"type":"say","who":"姜维","text":"钟会这次的攻势又被我们击破，看来他已经是没有能力攻破剑门关了。"},{"type":"say","who":"姜维","text":"只要再继续撑下去，应该就可以等到他粮尽撤退的那一刻。士兵大事不好了，邓艾军队通过阴平小路，直接奇袭我军后方。士兵成都那边派出卫将军前往迎击，结果…"},{"type":"say","who":"姜维","text":"结果怎么样？士兵结果…包括卫将军父子以下，尚书郎黄崇、羽林右部督李球和尚书张遵等人全部战死，绵竹关也失守了…"},{"type":"say","who":"姜维","text":"什么？！怎么会这样…"},{"type":"say","who":"诸葛果","text":"………"},{"type":"say","who":"杨兰","text":"（诸葛果的脸色都发青了，我看她现在光是站著就很勉强了…）"},{"type":"say","who":"袁綝","text":"（可恶，这时候我根本没办法帮她什么，她的眼中根本没有我。）"},{"type":"say","who":"姜维","text":"那么圣上的情况如何？士兵还不清楚，有说逃到南中，也说逃到东吴，总之现在成都那边是一片混乱。"},{"type":"say","who":"姜维","text":"那么再去探听一些有效的情报，麻烦你了。"},{"type":"say","who":"诸葛果","text":"主公…现在应该要…"},{"type":"say","who":"杨兰","text":"够了！"},{"type":"say","who":"杨兰","text":"你不是昨天感染风寒还未愈吗？为什么急著跑出来，快点回去养病。"},{"type":"say","who":"诸葛果","text":"我没有感染风寒…"},{"type":"say","who":"杨兰","text":"我说你有就是有！"},{"type":"say","who":"杨兰","text":"姜维！我要把这个连自己生病都搞不清楚的笨女人带走，你们慢慢开会吧。"},{"type":"say","who":"姜维","text":"（杨兰，这次又欠你一次，诸葛果现在应该已经悲伤得无以复加了吧。）"},{"type":"say","who":"宁随","text":"唉…想不到街亭的悲剧会再度重演，思远欠缺实战经验，要他去面对邓艾简直就是羊入虎口。"},{"type":"say","who":"董厥","text":"我不懂，为什么思远不赶快求援，照理说我们从剑门关赶回去也还来得及。"},{"type":"say","who":"来忠","text":"想也知道为什么，还不是怕大将军回去之后会回复权力，所以他宁可把大汉将士葬送掉也坚持要独自面对邓艾。"},{"type":"say","who":"董厥","text":"如果真是这样…思远你还真是对不起大汉，对不起丞相呀…"},{"type":"say","who":"姜维","text":"现在我们应该放弃剑门关，赶快回去救援成都。"},{"type":"say","who":"向充","text":"可是…万一钟会紧追在后怎么办？"},{"type":"say","who":"姜维","text":"不用担心，钟会新败，就算要重整旗鼓来进攻也要一段时间。"},{"type":"say","who":"宁随","text":"伯约，你认为现在回去还来得及？陛下不可能就那样在成都坐以待毙的。"},{"type":"say","who":"姜维","text":"所以你认为…"},{"type":"say","who":"宁随","text":"陛下眼前只有三个选择，第一个选择是前往南中。"},{"type":"say","who":"宁随","text":"但南中地区至今仍欠缺有效统治，南中大姓在忽然面对强大外敌的情况也很难保证他们的忠诚"},{"type":"say","who":"宁随","text":"就算是曾任虎步监的孟琰，也不敢保证他在危难当头会不会选择保护孟家的利益，所以我认为不会选择这路。"},{"type":"say","who":"宁随","text":"投奔东吴确实是比较可能的决定，因为东吴有长江天险，纵然大汉灭亡也足以自保。"},{"type":"say","who":"宁随","text":"现在如果我们前往巴东，或许还有追上陛下的可能性。"},{"type":"say","who":"宁随","text":"之后在该地集结战力，和东吴荆州部队联手，看要继续顺江投奔东吴，或是保住巴东也都不是问题。"},{"type":"say","who":"姜维","text":"第三个选择是什么？"},{"type":"say","who":"宁随","text":"我不想说…只是一旦陛下做出那样的选择，我们也就没戏唱了…"},{"type":"say","who":"姜维","text":"（不，还有机会，如果陛下愿意在成都抵抗的话，一切都还有转机。）"},{"type":"say","who":"姜维","text":"众人听好，现在舍弃剑门关，全军往巴东方向前进。"},{"type":"say","who":"袁綝","text":"这是为什么？如果要去援救成都，这样的行进方向未免太迂回了。"},{"type":"say","who":"姜维","text":"显通，请仔细想想现在剑门关通往成都的要地涪县在谁手上？"},{"type":"say","who":"袁綝","text":"贼军是吗？我懂了，如果遭遇敌人抵抗的话，抵达成都的时间反而更久。"},{"type":"say","who":"袁綝","text":"万一再碰上钟会夹击，到时我军只有战败一途。"},{"type":"say","who":"姜维","text":"是的，这就是所谓孙子的“迂直之计”。"},{"type":"say","who":"姜维","text":"抵达成都之后，我军可以优势兵力击溃邓艾，之后在成都抓准敌人行进的时间差，予以个别急破。"},{"type":"say","who":"廖化","text":"敌人是我们的三倍多，真的可以这么顺利个别击破？"},{"type":"say","who":"姜维","text":"相信我，钟会就是仗著优势兵力，所以才会采取分兵前进的战略包围策略。"},{"type":"say","who":"廖化","text":"那么为什么不留部分部队守住剑门关，好抵挡钟会的部队？"},{"type":"say","who":"姜维","text":"如果留的人少，则无法发挥功效，如果留的人多，则我军用来迎击邓艾的部队就少。"},{"type":"say","who":"宁随","text":"（更何况之前出过蒋舒这样的叛徒，天知道被留下的人会不会再跑出另一个蒋舒。）"},{"type":"say","who":"姜维","text":"一切都还有希望，只要照著这个策略走，歼灭敌军绝非难事。"},{"type":"say","who":"句扶","text":"不愧是大将，在危急之时还是可以想出这么强大的策略。"},{"type":"say","who":"姜维","text":"（那是胡扯的。钟会虽然一定会分兵，但是以双方人数的差距，每个分队的人数还是和我军相当。）"},{"type":"say","who":"姜维","text":"（在势均力敌的情况下，我军能够快速击破敌人的机会很小，到时拖久，钟会各路军再包上来，我军还是会败。）"},{"type":"say","who":"姜维","text":"（我已经没办法了，只好赌上最后一点机会，尽己所能看自己能和钟会大军周旋到什么地步。）诸葛果的心情剑门关附近"},{"type":"say","who":"杨兰","text":"真是的，你这女人还真是倔强，有想说的就说，想哭就哭，为什么要这样逞强？"},{"type":"say","who":"杨兰","text":"我就在傅佥阵亡时大哭一场，哭完就没事了。"},{"type":"say","who":"诸葛果","text":"笑也一生，哭也一生，所以今生必不流泪。"},{"type":"say","who":"杨兰","text":"你还真是倔强得可怕。"},{"type":"say","who":"诸葛果","text":"小瞻从小就喜欢黏著我跑，最喜欢说长大要保护姊姊我…"},{"type":"say","who":"诸葛果","text":"但我知道小瞻其实是个柔弱又胆小的男孩，比起作战，他还比较喜欢书画。"},{"type":"say","who":"诸葛果","text":"结果他就是这样一路逞强，压抑自己的兴趣而成长的。"},{"type":"say","who":"杨兰","text":"（诸葛家的人都这么喜欢逞强，真是好可怕的血统…）"},{"type":"say","who":"诸葛果","text":"我一直在想，如果能早点告诉小瞻，请他不要勉强自己，说不定他会过得快乐些，也不至于仇视主公，更不至于会战死。"},{"type":"say","who":"诸葛果","text":"是我的疏忽害了小瞻、害了主公，也害了大汉…"},{"type":"say","who":"杨兰","text":"真是的，你这个女人简直就是被虐狂！"},{"type":"say","who":"诸葛果","text":"请问这是…"},{"type":"say","who":"杨兰","text":"别以为我有百合倾向，只是我这样看不见你的脸而已。"},{"type":"say","who":"诸葛果","text":"………追击剑门关魏军营帐"},{"type":"say","who":"钟会","text":"前几天相国那边来信，说邓艾要从阴平小路突袭蜀国腹地，我本来以为那老头痴呆了…"},{"type":"say","who":"钟会","text":"没想到昨天姜维居然丢下剑门关逃走…"},{"type":"say","who":"杜预","text":"事情其实就很明显了，邓艾突袭成功，所以姜维必须弃城逃走。"},{"type":"say","who":"卫瓘","text":"（问题是…钟会打个半死都打不下来的剑门关，却因为邓艾的奇袭而得手，这下钟会这主帅的脸可丢大了。）"},{"type":"say","who":"胡烈","text":"姜维要回军，一定会经过涪县，所以我们只要朝著涪县进军，一定可以遇到姜维。"},{"type":"say","who":"钟会","text":"不错，一定要追上姜维，不然我们可会被陇西那群猴子嘲笑的。"},{"type":"say","who":"钟会","text":"（如果不在邓艾和姜维交战前追上的话，这次征蜀作战的功劳将全被邓艾夺去，到时我在相国心中还有地位？）救援成都巴中姜维军营帐"},{"type":"say","who":"姜维","text":"没想到会在这里遇上右大将军的军队。"},{"type":"say","who":"阎宇","text":"我接到成都的召集命令，于是率领永安的援军前往成都。"},{"type":"say","who":"阎宇","text":"中途听到邓艾突袭涪县的消息，急忙加速往成都前进。哪知道诸葛瞻居然不等我们援军到达，就率军去迎战邓艾…"},{"type":"say","who":"宁随","text":"确实如果等到右大将军的部队到达，再由实战经验较为丰富的右大将军来领兵，至少不会落得全军覆没的田地。"},{"type":"say","who":"阎宇","text":"现在说这些都已经太晚了，我就是知道发生这样的事情，所以把军队停在巴中，等候圣上前来。"},{"type":"say","who":"阎宇","text":"听说陛下已经舍弃成都，率领车驾前往此地。"},{"type":"say","who":"姜维","text":"陛下选择不抵抗也没关系，只要他的车驾前来，我们迎接陛下后还是可以回师收复成都。"},{"type":"say","who":"阎宇","text":"话虽如此，但我们在此地已经等了几天…"},{"type":"say","who":"姜维","text":"嗯，实在太久了。为什么到现在都还看不到圣上车驾的影子，难道圣上真的准备逃往南中？"},{"type":"say","who":"宁随","text":"南中的霍绍先不久前也来信说没有看到圣驾，看来陛下确实没有往那个地方去。"},{"type":"say","who":"阎宇","text":"那么陛下到底往哪里去了？"},{"type":"say","who":"姜维","text":"我看我们还是先往成都再做打算吧。"},{"type":"say","who":"姜维","text":"（只是到了成都，面对钟会和邓艾的夹击，我可是一点把握也没有。不，我更没有把握的是万一……不会的，一定不会的。）"},{"type":"say","who":"宁随","text":"（伯约，这仗不会打了…陛下看来已经决定选择第三条路…一条让大汉上下军民最痛心的路…）"},{"type":"say","who":"宁随","text":"（丞相，请恕马谡无能，居然不能守护您苦心经营的大汉…）钟会失算涪县魏军营帐"},{"type":"say","who":"钟会","text":"你说这里完全没有看到姜维军队经过的迹象？"},{"type":"say","who":"胡烈","text":"没错，完全没有经过的迹象。反而有看见陇西军队驻扎过这里的痕迹。"},{"type":"say","who":"钟会","text":"这邓艾居然也不在这里，那他们两个人到哪里去了…"},{"type":"say","who":"羊琇","text":"会不会往巴东地方逃窜了？姜维过去对邓艾没有胜利的纪录，所以与其面对邓艾，不如往巴东暂避其锋。"},{"type":"say","who":"钟会","text":"巴东是吗？这确实是种可能，不过我不认为姜维是因为害怕邓艾才这样做…想必是发生了什么事情。士兵报告镇西将军，征西将军从成都来信，请您过目。"},{"type":"say","who":"钟会","text":"从成都来信…糟了！"},{"type":"say","who":"王韬","text":"莫非是邓艾打败仗？这也不意外，这老糊涂还真以为他那点军队可以攻下蜀地。"},{"type":"say","who":"杜预","text":"不，从成都来信就表示，邓艾已经攻下成都了。"},{"type":"say","who":"钟会","text":"（怎么会这样？我苦心等候的机会，我精心策画的战略，转眼间全都被邓艾破坏掉了。）"},{"type":"say","who":"钟会","text":"（我刻意把他丢到偏远地方去牵制姜维，哪知道他居然想到从那里翻过崇山峻岭，一口气攻破成都。）"},{"type":"say","who":"钟会","text":"（这下真的完蛋了，我率领十几万大军，没有建立任何功劳，而邓艾却创造灭蜀的奇迹。）"},{"type":"say","who":"钟会","text":"（两相比较之下，我在相国面前还会有地位吗？）"},{"type":"say","who":"钟会","text":"（不行，我不能就这样认输！）"},{"type":"say","who":"钟会","text":"胡烈和庞会，你们继续去追击姜维。"},{"type":"choice","options":[{"text":"是！"},{"text":"是！"}]},{"type":"say","who":"卫瓘","text":"镇西将军，邓艾刚攻下成都，为了避免他放纵士卒劫掠，我想先前往该地维持治安。"},{"type":"say","who":"钟会","text":"伯玉为什么要如此急忙离开这里，莫非是认为待在这里没有前途？"},{"type":"say","who":"卫瓘","text":"那可是天大的误会，难道你希望我这个监军一直待在你身边？"},{"type":"say","who":"钟会","text":"（这家伙说的倒也有道理，让他去监视邓艾，反而让我落得轻松。）"},{"type":"say","who":"钟会","text":"（他自请去成都，就是看上邓艾可能会因功而骄，随时准备打他小报告让他失势。）"},{"type":"say","who":"钟会","text":"（由此看来，这个卫瓘可是个不折不扣的大内高手。）投降命令郪县姜维军营帐"},{"type":"say","who":"蒋显","text":"大将军…大势已去了…"},{"type":"say","who":"刘敏","text":"你说清楚一点！为什么大势已去了？"},{"type":"say","who":"蒋显","text":"陛下已经投降邓艾，我此行就是奉命来命大将军就地投降的。"},{"type":"say","who":"句扶","text":"怎么会这样？为什么会这样！"},{"type":"say","who":"袁綝","text":"不可原谅！陛下这样做，简直就是把先帝的心血结晶拱手送人！"},{"type":"say","who":"袁綝","text":"义父，孩儿没能实现您的托付，眼睁睁看著大汉灭亡，实在无脸见您了。"},{"type":"say","who":"姜维","text":"陛下就这样放弃了大汉百万军民？他把先帝的志业放在哪里？丞相的遗愿放在哪里？"},{"type":"say","who":"姜维","text":"我苦心追求的，难道就是这样的结果？我在剑门关死守是为什么？"},{"type":"say","who":"姜维","text":"我以为在这里可以等到陛下的车驾，到最后却只有等来这样的降书？"},{"type":"say","who":"姜维","text":"苍天啊！告诉我这不是真的吧！为什么陛下会这么狠心抛弃自己的将士？"},{"type":"say","who":"姜维","text":"呜呜呜呜呜…啊啊啊啊啊…………"},{"type":"say","who":"杨兰","text":"（姜维第一次在人前痛哭，看得我心都碎了。）"},{"type":"say","who":"诸葛果","text":"………"},{"type":"say","who":"宁随","text":"（果然不出所料，陛下选择的是这第三条路，既是最轻松，又是最辛苦的路。）"},{"type":"say","who":"蒋显","text":"请大将军保重自己，如此我们才可以在大将军的领导下做打算。"},{"type":"say","who":"姜维","text":"（不行，我不能在这时候认输，不管再怎么绝望的情况，都会有一丝机会可以把握…）"},{"type":"say","who":"姜维","text":"（但是现在外有强敌，主上又投降，我还能怎么办呢？）"},{"type":"say","who":"姜维","text":"（等一下…钟会、邓艾、司马昭…这三个人之间难道不会有冲突？邓艾立下奇功，钟会不会眼红？司马昭不会猜忌？）"},{"type":"say","who":"姜维","text":"（对！还是有办法的。只是…进行计画以前，我必须向敌人屈膝，这是何等的耻辱？）"},{"type":"say","who":"姜维","text":"（不对！就算受辱又如何？我姜维的名声又算得了什么？哪怕赐我人世间所有的苦难，我也要完成复国的大业。）"},{"type":"say","who":"姜维","text":"（我不会放弃的，现在放弃的话，大汉就结束了。）"},{"type":"say","who":"句扶","text":"事到如今还说什么！回头和钟会拚个鱼死网破也好！宁可战死，也不愿做亡国奴！"},{"type":"say","who":"赵统","text":"我也赞成！先父数十年奋斗的心血，不能这样拱手让人！我赵统宁死不降。"},{"type":"say","who":"张翼","text":"我也不能认同投降的想法，虽说我不喜欢外州人当权，但不代表我愿意接受曹贼的统治！"},{"type":"say","who":"张翼","text":"那些打著益州人保卫乡土的名号投降的人，其实才是不折不扣的卖乡贼！"},{"type":"say","who":"姜维","text":"几位的心情我很明白，但是现在敌人的兵力超过我军三倍，而且现在无险可据，回头应战只是白白送死。"},{"type":"say","who":"姜维","text":"各位或许认为战死可以搏得忠烈美名，但白白断送复国之机岂不可惜？"},{"type":"say","who":"阎宇","text":"大将军，我认为事情还不至于到绝望的地步，如果我们退守巴东一带，然后传令聚集全国兵马，或许还有光复希望。"},{"type":"say","who":"阎宇","text":"就算不能光复，至少还可以偏安一方，保存大汉最后的生机。"},{"type":"say","who":"姜维","text":"如果说陛下没有投降，而是在我们这里的话，或许这样的想法还不错。"},{"type":"say","who":"姜维","text":"但是现在陛下在别人手上，内地的州县恐怕也已经大量投降敌方，我们能得到的响应将会非常有限。"},{"type":"say","who":"阎宇","text":"确实如此…"},{"type":"say","who":"董厥","text":"那么现在我们该怎么办？"},{"type":"say","who":"姜维","text":"可供选择的选项只有一个…"},{"type":"say","who":"廖化","text":"还有选择？我实在是想不到还有什么选择了。"},{"type":"say","who":"诸葛果","text":"主公是说，我们可以投降…"},{"type":"say","who":"廖化","text":"投降？开什么玩笑！到时我怎么有脸去那边见关将军？"},{"type":"say","who":"向充","text":"我向充虽为文官，但是也愿意随时为大汉殉难！"},{"type":"say","who":"袁綝","text":"不，我不认为伯约会这么单纯投降…"},{"type":"say","who":"来忠","text":"应该另有文章才对…"},{"type":"say","who":"诸葛果","text":"主公真正的意思，其实是想要效法勾践复国。"},{"type":"say","who":"刘敏","text":"原来如此…这可真是痛苦的决定。"},{"type":"say","who":"姜维","text":"多谢诸葛姑娘帮我说出这难以启齿的话，我的意见正是如此，假意投降，以待复国之机。"},{"type":"say","who":"姜维","text":"司马昭阴狠多疑，邓艾高傲孤僻，钟会狼子野心，这三人定有莫大的嫌隙，只要假意投降，从中挑拨，必有复国之望。"},{"type":"say","who":"董厥","text":"只是这三人都不是泛泛之辈，真的这么容易被挑拨吗？"},{"type":"say","who":"姜维","text":"就算前方险阻重重，但我也不会放弃。因为现在放弃，一切都结束了。"},{"type":"say","who":"马岱","text":"伯约，万一失败，你将会身败名裂，被后世嘲笑，这样也无所谓？"},{"type":"say","who":"姜维","text":"我宁愿经过这样的努力而死，也不要逞匹夫之勇，白白浪费将士的性命。"},{"type":"say","who":"姜维","text":"姜维个人的名誉根本算不了什么，如果最后能完成复国大业，纵受千夫所指也甘之如饴。"},{"type":"say","who":"廖化","text":"我已经明白伯约的想法，如果有什么需要的地方，请尽管吩咐，就算拚上这条老命也要帮上一点忙！"},{"type":"say","who":"姜维","text":"那么…因为这次的行动非常危险，所以我不希望所有人都参与这次的行动。"},{"type":"say","who":"姜维","text":"首先，我希望有人能率领部分军队先离开这里。"},{"type":"say","who":"姜维","text":"为了避免意外，也为了留下大汉最后的战力，因此请刘、赵两位将军带走三千人左右的部队前往南中。"},{"type":"say","who":"姜维","text":"那里有绍先的南中部队可以依赖，加上气候和地形险恶，贼军不会愿意花这些代价去追击的。"},{"type":"say","who":"刘敏","text":"我明白了，这些军队就交给我们吧！到时复国成功，可要第一个通知在南中的我们。"},{"type":"say","who":"赵统","text":"大将军…"},{"type":"say","who":"姜维","text":"拜托你了，希望你连赵广的份一起奋斗。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"姜维","text":"另外马岱将军也请留下来，你可以从这里到北方，就这样返回马家的故居地吧。"},{"type":"say","who":"马岱","text":"你是认为我没有和大汉共存亡的决心？"},{"type":"say","who":"姜维","text":"不，请将军仔细想想马家这些年的遭遇。"},{"type":"say","who":"姜维","text":"曾经雄霸一时，让曹操都闻风丧胆的扶风马家，现在却落得人丁凋零，连祭祀都有问题的惨状。"},{"type":"say","who":"姜维","text":"现在大汉已经消亡，而马家为大汉的付出也足够了，所以我希望马将军能为自己家族存续做考量。"},{"type":"say","who":"马岱","text":"那么在临走之前，还是请让我为族兄当年在冀城所为之事道歉。"},{"type":"say","who":"姜维","text":"已经没关系了，事情都已经过去那么久，再深的怨恨也该烟消云散。"},{"type":"say","who":"马岱","text":"（不，其实有个人还是让我很担心，令明的儿子现在好像还在魏军，只怕他还是记著那杀父之仇。）"},{"type":"say","who":"姜维","text":"伯岐，我希望你也和他们一起去南中，只要南中有你，贼军一定不敢轻举妄动。"},{"type":"say","who":"张嶷","text":"伯约，你真狡猾，居然丢给我一个完全无法拒绝的任务。"},{"type":"say","who":"姜维","text":"杨兰，我希望你带诸葛姑娘一起离开这里，你们已经陪伴我够久了，我不能让你们跟我继续冒险。"},{"type":"say","who":"诸葛果","text":"主公，我的命一直是您的。"},{"type":"say","who":"杨兰","text":"你以为我们是怕危险的人？"},{"type":"say","who":"姜维","text":"拜托，这是我最后的请求，我希望诸葛姑娘能回去和丞相夫人团聚，而杨兰你能够回天水帮忙照顾我母亲。"},{"type":"say","who":"杨兰","text":"这……"},{"type":"say","who":"诸葛果","text":"主公，这是命令吗？"},{"type":"say","who":"姜维","text":"是的，我命令你回去汉中，并且好好地活著。"},{"type":"say","who":"诸葛果","text":"既然这样，诸葛果领命！"},{"type":"say","who":"杨兰","text":"等一下，你到底在搞什么？"},{"type":"say","who":"诸葛果","text":"主公的命令不可不从。"},{"type":"say","who":"姜维","text":"谢谢你了，这样我也可以安心进行我的复国计画。悲愤之举郪县附近"},{"type":"say","who":"张翼","text":"这些士兵听到要投降的消息，全部都悲愤不已，拔刀砍山石泄愤。"},{"type":"say","who":"廖化","text":"毕竟我们的计画不能让太多人知道，让将士们稍微发泄一下也好。"},{"type":"say","who":"袁綝","text":"空有满腹对敌人的怒火，却被一道诏书给浇熄，任谁都感到悲愤。"},{"type":"say","who":"袁綝","text":"要是没有这个复国的希望，我的怒火绝对不是砍山石就能平息的。"},{"type":"say","who":"句扶","text":"其实我也想这样做，我现在满腔的悲愤之情，可不会因这样虚幻的计画而得到纾解。"},{"type":"say","who":"宁随","text":"伯约，这可是条不归路，就让我陪你走下去吧…"},{"type":"say","who":"姜维","text":"好吧，就让我们出发前往钟会大营，接下来可不能回头了。姜维归降涪县魏军营帐"},{"type":"say","who":"钟会","text":"我已经等你很久了，伯约你为什么来这么迟？"},{"type":"say","who":"姜维","text":"姜维身为大将军，统率全国军队，现在来到还算早了。"},{"type":"say","who":"钟会","text":"哦…说得也是…"},{"type":"say","who":"句安","text":"（哈哈哈，到最后你还不是乖乖来了，准备当我的小弟吧！）"},{"type":"say","who":"蒋舒","text":"（看见姜维也来投降，似乎我当初的决定是正确的，我现在可一点也不后悔了。）"},{"type":"say","who":"钟会","text":"我想问你一件事情，到现在你还是坚持你当初说的话？你还是认为你持守的理想没有错？"},{"type":"say","who":"钟会","text":"如果当时你献出剑门关投降的话，我们应该已经在成都举杯庆祝，而非以现在这样难堪的方式见面。"},{"type":"say","who":"姜维","text":"我坚持的理想并没有变，既然是奉主诏命投降，姜维问心无愧！"},{"type":"say","who":"钟会","text":"还真是愚忠呢…"},{"type":"say","who":"姜维","text":"如果姜维愚忠，应该马上率领手下四万将士，和你决一死战，拚个同归于尽。"},{"type":"say","who":"姜维","text":"然而我没有这样做，就是为了顾及将士的性命，也为了让蜀地停止兵祸。"},{"type":"say","who":"钟会","text":"说得好，不卑不亢，应对得体，实在是了不起的人才！"},{"type":"say","who":"钟会","text":"这些印绶我全部还给你们，蜀国的军队还是继续由你们来统率。"},{"type":"say","who":"姜维","text":"多谢钟将军，如果可以的话，请让我写信给关、汉、还有黄金城的守将，要他们一并前来归降。"},{"type":"say","who":"钟会","text":"如果能这样的话，实在是帮了大忙，我在那边至少派有一万人的围城部队，实在有点困扰。"},{"type":"say","who":"姜维","text":"那么我就去准备一下…"},{"type":"say","who":"钟会","text":"请…"},{"type":"say","who":"钟会","text":"元凯，你怎么看姜维？"},{"type":"say","who":"杜预","text":"确实是个了不起的人才，只可惜蜀国地小民贫，不足以让他发挥才能，最终使他变成亡国降臣，实在可惜。"},{"type":"say","who":"钟会","text":"就算如此，他的才能没有这么容易被掩盖的。"},{"type":"say","who":"钟会","text":"以我来看，以姜伯约和中土名士相比，就算诸葛诞和夏侯玄都比不过他。"},{"type":"say","who":"杜预","text":"（为什么他会对一个降将这么看重，还让他继续统领旧有部队。）"},{"type":"say","who":"杜预","text":"（一个原因或许是他真的很欣赏他，另一个原因恐怕…他图谋不轨…）钟毓的警告洛阳司马家"},{"type":"say","who":"司马昭","text":"我以为稚叔你在荆州养病，怎么会千里迢迢赶到洛阳？"},{"type":"say","who":"钟毓","text":"当我听说相国您任命我弟弟去征蜀时，几乎是吓得魂飞魄散，哪有时间在那里生病呢？"},{"type":"say","who":"司马昭","text":"士季足智多谋，这次能够成功灭蜀，他也立下相当的汗马功劳，我褒奖他都来不及了，你何必吓成这样。"},{"type":"say","who":"钟毓","text":"我这弟弟心怀诡诈，没有人可以保证他会做出什么事情，不可以教他独当一面。"},{"type":"say","who":"司马昭","text":"嗯…过去邵悌和元姬都对我说过同样的话，加上之前诸葛绪的事情，确实让我有点挂心…"},{"type":"say","who":"司马昭","text":"只是你是他兄长，本来应该友爱手足，为什么却反过来指控他？要知道，就算是基于一片忠心，我也不会欣赏这种行为。"},{"type":"say","who":"钟毓","text":"我们颖川钟家从高祖父钟皓以来，就是和陈家与荀家并称的名士家族。"},{"type":"say","who":"钟毓","text":"而如今我们钟家却因为钟会而即将出现灭族的危机，我又怎么能不先预防？我密告钟会是为了守护钟家，是尽大孝。"},{"type":"say","who":"司马昭","text":"原来如此…我明白了。就请稚叔你好好保重，万一钟会真的做出什么叛逆的事情，我也绝不会让钟家覆亡的。"},{"type":"say","who":"钟毓","text":"多谢相国。如此，我也可以安心把钟家人托付给您了。司马昭震怒洛阳相国府军事行动有种形势是所谓：先声夺人，就可以使敌人屈服，战斗不过是次要的。我们如果利用灭蜀的余威，动下攻击东吴，东吴人民惊恐，正是袭卷之时。但是现在将士疲劳，应该稍微暂缓攻击；可留陇右兵二万人、蜀兵二万人，煮盐冶铁，为军事和屯垦之用，并造舟船，作出将顺流而下的态势，然后遣使告知东吴利害，则吴国必归化，可不征而定。如今应厚待刘禅，给吴帝孙休做榜样，且不要急著遣送至京城；可封刘禅为扶风王，封其子为公候，以该郡内之县为食地，把董卓所建的郿坞赐给他们为住处，以及仆人、钱财，以显示归顺后的优良待遇。然后把广陵、城阳作为封国，以待吴人，如此恩威并施，吴人就会望风而从了。"},{"type":"say","who":"贾充","text":"这实在是太不像话了！邓艾以为他是谁呀，居然还插手军略大事！"},{"type":"say","who":"司马昭","text":"的确，如果当时不是元姬拉住我，我可能早就当场发飙了。"},{"type":"say","who":"司马昭","text":"当邓艾攻破成都，收降刘禅之时，我本来以为他是可以倚靠的人才。"},{"type":"say","who":"司马昭","text":"要知道，这场战争我可没有胜利的把握，特别是听到姜维进入剑门关后，我都已经做好输掉的打算。"},{"type":"say","who":"司马昭","text":"邓艾却能扭转乾坤，打赢这场战争，让我创造前所未有的功业，撑起自己升任晋王的正当性。"},{"type":"say","who":"贾充","text":"千万不能给邓艾重赏，这个人居功自傲，将来必成大患。"},{"type":"say","who":"司马昭","text":"话是没错，不过有功不赏，你是要我失去部下的信任？"},{"type":"say","who":"司马昭","text":"放心吧，我已经做好安排了…擢升邓艾当太尉，采邑两万户。钟会则当司徒，采邑一万户。"},{"type":"say","who":"司马昭","text":"我让伯玉去宣布这个消息，并且给邓艾最后一次机会。如果他再这么愚蠢的话…"},{"type":"say","who":"夏侯和","text":"光注意邓艾似乎还不够…"},{"type":"say","who":"司马昭","text":"义权，你有什么看法？"},{"type":"say","who":"夏侯和","text":"钟会狼子野心，拥兵十几万，若再加上归降蜀军，恐怕会有将近二十万的人马。"},{"type":"say","who":"夏侯和","text":"之前雍州刺史诸葛绪在没有您同意的情况下，就被押送洛阳，难道您忘记钟会如此胆大妄为？"},{"type":"say","who":"司马昭","text":"嗯…其实早在你之前，已故的稚叔就已经要我小心他弟弟，只是一时间我无法同时处理邓艾和钟会两个人。"},{"type":"say","who":"司马昭","text":"义权，你就充当使者前去蜀地一趟吧。"},{"type":"say","who":"司马昭","text":"不用担心在那边没人接应，至少杜元凯和羊稚舒都是可以信赖的人。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"夏侯和","text":"（二哥，看来我们扳倒钟会的计画进行得还挺顺利的。只是为什么二哥忽然要对付钟会呢？我们不是应该对付司马家？）洛阳太后寝宫道别"},{"type":"say","who":"郭太后","text":"看来司马昭还是肯尊重我这个没用的太后，他居然会答应放你回到洛阳…"},{"type":"say","who":"曹绫","text":"那是因为我已经没有任何方法可以动摇他司马家的统治了。"},{"type":"say","who":"郭太后","text":"这样也好，让你卸下这些重担，你也可以活得轻松一点。"},{"type":"say","who":"郭太后","text":"你知道许仪的事情了吗？"},{"type":"say","who":"曹绫","text":"虽然对外宣称是因为修路不力而被正法，但是实情我想不是这样…他真的很傻。"},{"type":"say","who":"郭太后","text":"我请你回来其实就是要告诉你，蜀国灭亡就表示曹家的气数已尽，你以后不要再为曹家做什么事情了。"},{"type":"say","who":"郭太后","text":"明皇帝那边就让我去和他说，我这个当嫂子的，可不会让明皇帝来责怪你。"},{"type":"say","who":"曹绫","text":"我真的什么都没有做到…什么都没有…"},{"type":"say","who":"郭太后","text":"已经很够了，从今而后，你应该为自己而活，不要再考虑其他的事情了。"},{"type":"say","who":"曹绫","text":"（不，其实还有一线希望…）公元二六三年十二月，曹魏郭太后逝世。她虽然是明帝的妻子，享有极度尊崇的地位，然而却屡次被司马家抬出来当作是权力的正当基础。明明身为曹家人，却变成司马家用来篡夺曹家政权的工具。在这一天，她终于从这悲惨的处境中解脱。骄纵的表现成都皇宫"},{"type":"say","who":"邓艾","text":"哈哈哈哈哈…你们还真是走运，幸好遇上我，才有今日的安泰。若遇到像是吴汉这样的人，恐怕早已被杀光了。"},{"type":"say","who":"樊建","text":"您说的很有道理…"},{"type":"say","who":"樊建","text":"（他说的话虽然很不中听，但想起吴汉过去杀尽公孙述、延岑一族，纵容属下兵士掠夺，焚烧宫室，我们确实是幸运的。）"},{"type":"say","who":"郤正","text":"（这个邓艾越来越骄纵了，前几天居然还在绵竹筑台表彰自己的功劳，再这样下去，他恐怕真的会倒楣。）"},{"type":"say","who":"邓艾","text":"对了，说到那个姜维，其实他算不错，也可以说是一代英雄，只可惜倒楣碰上了我，哈哈哈…"},{"type":"say","who":"郤正","text":"（要是你们交换立场，今天在这边笑的应该是伯约吧…）"},{"type":"say","who":"邓艾","text":"咦？！这不是监军吗？你怎么会过来呢？"},{"type":"say","who":"卫瓘","text":"咳咳…"},{"type":"say","who":"卫瓘","text":"首先相国已经请求圣上擢升您成为太尉，今后您可是位列三公。"},{"type":"say","who":"邓艾","text":"邓艾何德何能，居然能从一个牧牛小童成为三公，实在是不胜感激。"},{"type":"say","who":"邓艾","text":"对了，你刚才提到相国…"},{"type":"say","who":"卫瓘","text":"没错，大将军已经接受圣上的赏赐，正式成为相国，并且享有晋公的封号。"},{"type":"say","who":"邓艾","text":"那还真是可喜可贺。"},{"type":"say","who":"卫瓘","text":"相国那边还有另外的事情要交代。"},{"type":"say","who":"邓艾","text":"请说。"},{"type":"say","who":"卫瓘","text":"任何事情都该先请示，不可自做主张。"},{"type":"say","who":"邓艾","text":"哼，果然是这样…"},{"type":"say","who":"卫瓘","text":"等…等一下…您这话是什么意思？"},{"type":"say","who":"邓艾","text":"奉命出征，今敌已投降，我承制任命以安抚初附之民，合乎权宜。"},{"type":"say","who":"邓艾","text":"蜀国已经归附，疆域扩张到南海，东接吴会，应该早日求取安定。如果等待中央命令，道路往返，必将拖延时日。"},{"type":"say","who":"邓艾","text":"《春秋》上说，‘大夫出征时，只要有可以安定社稷、利于国家之事，可以断然实行。’"},{"type":"say","who":"邓艾","text":"而今东吴没有臣服，国土和蜀中相连，不应该拘泥常态，失掉时机。"},{"type":"say","who":"邓艾","text":"《孙子兵法》说：‘进不求名，退不避罪。’我虽无古人之节，但不会为了自保而损国家大事！"},{"type":"say","who":"卫瓘","text":"我明白了，这就传达给相国知道。"},{"type":"say","who":"卫瓘","text":"（邓艾呀，你居然不知道这是相国给你的最后机会。战场上的天才，居然在政治上这么白痴…）密议剑门关魏军营帐"},{"type":"say","who":"姜维","text":"在下曾听说，将军自从淮南平毌丘俭之乱以来，计谋从不失策，全靠您一人之力，才能完成那么大的功业！"},{"type":"say","who":"姜维","text":"现在您又平定了蜀国，您的威望震动天下，万民都称诵您的功劳。然而这样子功高震主，何处才是安身之所？"},{"type":"say","who":"姜维","text":"为什么不效法范蠡，泛舟江湖，用以保全自己的功业，保护自己的生命？"},{"type":"say","who":"钟会","text":"你的陈义太高，我办不到。而且现在时代不同，或许还有其他方法。"},{"type":"say","who":"姜维","text":"其他方法，用您的智力就可以完成了，哪里还需要我担心呢？"},{"type":"say","who":"钟会","text":"（莫非姜维也知道我内心的想法？确实我现在回去，不知道会遭到什么样的对待，过去有太多鸟尽弓藏的例子。）"},{"type":"say","who":"钟会","text":"（我手握十几万大军，论智力和谋略也不输司马昭，凭什么要回去任他宰割呢？）"},{"type":"say","who":"姜维","text":"倒是…最近您听过成都那边的传闻？"},{"type":"say","who":"钟会","text":"是说邓艾专横，有不臣之心？这不用伯约你说，整个蜀地有谁不知道？他那把功劳全部揽下来的作风，更让人不愉快。"},{"type":"say","who":"姜维","text":"既然这样，为什么还不采取行动？难道您真的认为洛阳那边会无动于衷？还是您心胸如此开阔？"},{"type":"say","who":"姜维","text":"邓艾靠著行险，侥幸成功，却表现出自己是灭蜀大功臣，完全不理会在剑门关浴血奋战，牵制住在下四万大军的您。"},{"type":"say","who":"钟会","text":"确实如此，于私我痛恨邓艾的倨傲态度，"},{"type":"say","who":"钟会","text":"于公来说，如果相国准备对邓艾动手的话，我们也该采取相对应的行动才行，不然被认为同谋就麻烦了。"},{"type":"say","who":"钟会","text":"只是…万一相国还没有准备要对邓艾动手，我们先发制人，恐怕会引起相国猜忌。"},{"type":"say","who":"姜维","text":"这也不难，我们驻扎的地方是剑门关，所有成都和洛阳的往来文书都要经过我们这边。"},{"type":"say","who":"钟会","text":"我懂了，拦截邓艾的书信，把里面的文句修改，套上悖逆狂傲的辞令。"},{"type":"say","who":"钟会","text":"然后相国的书信，则改成凌厉苛责的语气，让邓艾感到害怕，更容易做错事。"},{"type":"say","who":"姜维","text":"您对于修改书信应该很拿手，过去在下也听过您用一信就让全怿开城投降。"},{"type":"say","who":"钟会","text":"好，就如此行吧。同时我也会去探听卫瓘的口风，到时联合上表弹劾邓艾，一定可以给他致命一击。钟会和姜维之间因为同谋对付邓艾，交情日好，出则乘同轿，列坐时则位于同席。逐渐成为钟会最信赖的心腹。曹绫的智慧洛阳相国府"},{"type":"say","who":"贾充","text":"东乡公主为什么会在这个地方？"},{"type":"say","who":"司马昭","text":"不用紧张，因为太后在临终前坚持要见她一面，所以我才让她过来洛阳。"},{"type":"say","who":"司马昭","text":"现在想想，我还真庆幸当时的决定，否则我一下子还找不到人帮忙我。"},{"type":"say","who":"曹绫","text":"应该是关于邓艾和钟会的事情吧。"},{"type":"say","who":"司马昭","text":"既然公主知道，我也就不需要拐弯抹角。"},{"type":"say","who":"司马昭","text":"确实是邓艾和钟会这两个人让我很困扰，虽说他们是灭蜀的大英雄，但是现在都有叛逆的行为。"},{"type":"say","who":"曹绫","text":"既然有叛逆的行为，那么就该当机立断去抓他，否则等他积蓄实力，收揽人心，轻则成为刘备第二，重则威胁大魏江山。"},{"type":"say","who":"荀勖","text":"我也同意，邓艾先不说，那个钟会虽受您的恩典，但他本性不见得能思量忠义，不可不快快防备。"},{"type":"say","who":"贾充","text":"这女人一直是我们的敌人…"},{"type":"say","who":"司马昭","text":"不，我认为我们在这一点可以达成共识，没有人希望见到邓艾或是钟会造反。"},{"type":"say","who":"曹绫","text":"想要一口气解决邓艾和钟会，可以先放任这两人互咬，让钟会解决邓艾。之后你再亲自坐镇长安，表示对他的挑战。"},{"type":"say","who":"曹绫","text":"此时钟会只有两种选择，一是率领一群没有战斗意识的军队和你对决，二是投降，那么他此生将永远无法碰军队。"},{"type":"say","who":"魏舒","text":"怎么看都是最完美的策略，但是…还是有个小小疑点…如果钟会能够驱使蜀将为他作战呢？"},{"type":"say","who":"曹绫","text":"以现在钟会和蜀人相处的时间，施恩不及，积怨难消，他没有这本事驱使蜀人。"},{"type":"say","who":"曹绫","text":"况且就算他有这个本事，难道我大魏的相国没有办法面对这些亡国奴的挑战？"},{"type":"say","who":"司马昭","text":"好，一切都照你的想法来做。不过…我有个要求…"},{"type":"say","who":"曹绫","text":"和你一起前往长安是吗？没问题。"},{"type":"say","who":"司马昭","text":"（这个女人实在是太厉害了，我辗转反覆想了半天想出的方案，都不及她随口提出的周全。）"},{"type":"say","who":"司马昭","text":"（她的能力不下于元姬，甚至还在她之上。）"},{"type":"say","who":"司马昭","text":"（如果她不是曹氏宗族，或许能够成为我身边最得力的助手吧。）"},{"type":"say","who":"曹绫","text":"（没有计画的计画，没有谋略的谋略，姜维或许可以体会我的安排，但能不能成功，一切都要看天意了。）逮捕邓艾洛阳宫殿"},{"type":"say","who":"司马昭","text":"根据卫监军、钟司徒还有师纂的上书，邓艾自认有盖世奇功，居然假传圣旨，恣意在蜀地大封官员。"},{"type":"say","who":"司马昭","text":"臣认为应当即刻逮捕逆臣邓艾，避免蜀地得而复失。"},{"type":"say","who":"曹奂","text":"那就逮捕他吧。"},{"type":"say","who":"司马昭","text":"陛下，事情可没有这么简单…"},{"type":"say","who":"曹奂","text":"您还要朕做什么？"},{"type":"say","who":"司马昭","text":"为了避免邓艾反抗，臣已经派遣中护军贾充率领精锐中军一万人，从褒斜谷南下，进驻汉中。"},{"type":"say","who":"司马昭","text":"而陛下您也应该随同臣前往长安坐镇。"},{"type":"say","who":"曹奂","text":"一切都照相国你的意思吧…"},{"type":"say","who":"曹奂","text":"（反正我也没有这个权力说不…）"},{"type":"say","who":"司马昭","text":"巨源，现在任命你为行军司马，即刻前往邺城镇守。"},{"type":"say","who":"山涛","text":"这…"},{"type":"say","who":"司马昭","text":"别忘记你可是我们司马家的亲戚，因为这样的亲戚关系，我很多事情可都睁只眼闭只眼，例如说嵇康的事情…"},{"type":"say","who":"山涛","text":"遵命！我立刻启程前往邺城。"},{"type":"say","who":"邵悌","text":"相国，有一事下官不明白。"},{"type":"say","who":"邵悌","text":"钟会手下的兵力有邓艾的五六倍，您只要命令钟会去抓邓艾就可以了，不用自己去长安一趟吧？"},{"type":"say","who":"司马昭","text":"你难道忘了之前你跟我说的话吗，竟然还跟我说不用去长安？"},{"type":"say","who":"邵悌","text":"莫非相国也怀疑钟会会造反？"},{"type":"say","who":"司马昭","text":"我以诚信待人，别人就不会背负于我。"},{"type":"say","who":"司马昭","text":"前阵子贾充还问我，是不是怀疑钟会，我跟他说怎么会有这种道理，要你领兵出征，还可以回头怀疑你的忠诚呢？"},{"type":"say","who":"司马昭","text":"贾充也对此无话可说。总之我到了长安，一切就会自己结束了。"},{"type":"say","who":"羊祜","text":"（相国大人摆明就是怀疑钟会，这次南下目的除了要逮捕邓艾，还要顺便测试钟会的忠诚。）"},{"type":"say","who":"羊祜","text":"（万一钟会造反，十万大军足够平乱，而他如果没有造反，则可以趁机收回兵权。）"},{"type":"say","who":"羊祜","text":"（只是这样完美的计画，似乎还是存有一些破绽，要不然岳父也不会如此积极让夏侯义权前往益州。）公元二六四年元月，曹魏皇帝曹奂下令逮捕邓艾，用囚车押返洛阳。晋公司马昭怕邓艾抗命，派遣中护军贾充南下。而司马昭本人也亲率大军，侍奉皇帝曹奂，进驻长安。借刀杀人剑门关魏军营帐"},{"type":"say","who":"钟会","text":"我已经接到逮捕邓艾的命令，这下邓艾可完蛋了。"},{"type":"say","who":"姜维","text":"不，如果您亲自去逮捕邓艾，只怕陇西军会反抗，到时打得两败俱伤，对我们可没有好处。"},{"type":"say","who":"钟会","text":"那么该怎么做？"},{"type":"say","who":"姜维","text":"监军卫瓘，把这个任务交给他。"},{"type":"say","who":"姜维","text":"如果卫瓘被邓艾的士兵所杀，那么正好可以坐实他反叛的罪名。如果卫瓘成功逮捕邓艾，我们也乐得轻松。"},{"type":"say","who":"钟会","text":"妙妙妙，我这就修书给卫瓘，叫他前去逮捕邓艾。卫瓘奇谋成都陇西军帐外"},{"type":"say","who":"卫瓘","text":"（这该死的钟会，居然让我进行这九死一生的任务，摆明就是要我给邓艾宰。）"},{"type":"say","who":"卫瓘","text":"（不过如果我不接受，就算钟会不杀我，相国也不会放过我，只好拚了！）"},{"type":"say","who":"卫瓘","text":"诸位，我刚才接到皇帝诏书，要逮捕逆臣邓艾。"},{"type":"say","who":"卫瓘","text":"诸位请放心，只逮捕邓艾一个人，其他人都没有牵连。只是如果反抗的话，恐怕就得屠灭三族了。"},{"type":"say","who":"田续","text":"既然是皇帝的命令，我们能有什么办法呢？"},{"type":"say","who":"卫瓘","text":"（咦？看来陇西军不是每个人都忠于邓艾嘛。）"},{"type":"say","who":"丘本","text":"那是田续那家伙被邓将军修理过才会这样，我们平常可受到邓将军不少照顾。"},{"type":"say","who":"师纂","text":"不，我们是朝廷的部队，不是邓艾的私兵，就算对他再爱戴，贸然行动反而只会害了他。"},{"type":"say","who":"卫瓘","text":"（对了，这个师纂似乎是相国派来监视邓艾的人，看来在这时候可以发挥作用了。）"},{"type":"say","who":"王颀","text":"嗯…我们是朝廷的军队，没有必要进行反抗，成为真正的叛徒。"},{"type":"say","who":"杨欣","text":"我同意，这件事情我们会保持中立的。"},{"type":"say","who":"牵弘","text":"也罢，剩下就看丘本那个秃子了。"},{"type":"say","who":"丘本","text":"嗯…唉…随便你吧…只是接下来亲兵的关可没那么好过，你自己想办法吧。"},{"type":"say","who":"卫瓘","text":"那么师刺史，到时候押送太尉的工作就拜托你了。"},{"type":"say","who":"师纂","text":"师纂一定尽力而为。"},{"type":"say","who":"师纂","text":"（哈哈，该死的邓艾，现在落到老子手里了吧。）逮捕邓艾陇西军主营"},{"type":"say","who":"邓艾","text":"卫瓘，你在做什么？为什么一大早就把我父子绑起来？"},{"type":"say","who":"卫瓘","text":"奉皇帝诏命，逮捕逆臣邓艾。"},{"type":"say","who":"邓艾","text":"我是逆臣？哈哈哈…我明白了，白起所遭受的残酷待遇，今天又在这见到了。"},{"type":"say","who":"卫瓘","text":"奉旨办事，实在是不好意思。"},{"type":"say","who":"邓忠","text":"你少在这里假惺惺的了！"},{"type":"say","who":"卫瓘","text":"我和你无冤无仇，怎么可能会陷害你？"},{"type":"say","who":"卫瓘","text":"你仔细想自己做了什么事？如果不是你在成都胆大妄为，惹得相国生气，会有今天的局面？"},{"type":"say","who":"卫瓘","text":"当时相国托我带话给你，就是希望你能收敛，哪知道你仍然故我，还出言反驳，请问你还会有救吗？"},{"type":"say","who":"邓艾","text":"邓艾只知专心奉公，从来没有想过其他的事情。"},{"type":"say","who":"卫瓘","text":"是吗？当你被封三公的时候，你的表情可表现得不是那样。"},{"type":"say","who":"卫瓘","text":"我很同情你，但你也该知道，没有能力玩政治的人玩政治，最终都没好下场…步兵快点把邓将军还来！步兵你以为凭你这么一点人马，可以走得出去？"},{"type":"say","who":"卫瓘","text":"邓艾！让我走，我会上表帮你伸冤，如此你还有一线生机。"},{"type":"say","who":"卫瓘","text":"如果你放任手下杀我，到时候相国绝对不可能原谅你。"},{"type":"say","who":"卫瓘","text":"别忘记成都外面还有钟会的大军在那虎视眈眈，凭你陇西军的数量，根本就毫无胜算。"},{"type":"say","who":"邓艾","text":"卫监军，我可以相信你？"},{"type":"say","who":"卫瓘","text":"我卫伯玉说话算话，难道你没听过我的名声？我愿意以身家性命去担保太尉的清白。"},{"type":"say","who":"邓艾","text":"那么一切都拜托你了。"},{"type":"say","who":"卫瓘","text":"（好耶，这下应该过关了。剩下就是派师纂把邓艾运回洛阳就好。）谋反之议剑门关魏军营帐"},{"type":"say","who":"钟会","text":"哈哈哈，邓艾已经被逮捕了，看来卫瓘这家伙还真不简单。"},{"type":"say","who":"姜维","text":"事到如今，有些话或许我也该对您说了。"},{"type":"say","who":"钟会","text":"我会不了解你在想什么吗？姜伯约…"},{"type":"say","who":"姜维","text":"（难道他看破我的复国之计？）"},{"type":"say","who":"钟会","text":"你想要劝我起兵反叛对吗？其实我打从一开始就知道了。"},{"type":"say","who":"姜维","text":"既然您都知道了，我就直接说下去。"},{"type":"say","who":"姜维","text":"您被称做“今之张良”，但是您记得上一个有张良称号的人下场如何？"},{"type":"say","who":"钟会","text":"荀文若…被武皇帝活活逼死。"},{"type":"say","who":"姜维","text":"既然都这么清楚您即将面对的命运，为什么还要这样束手就擒？"},{"type":"say","who":"姜维","text":"论智慧，司马昭不如您。论用兵，司马昭也不如您，您又有什么理由屈居于他之下呢？"},{"type":"say","who":"钟会","text":"我有今天的地位，可都是司马家给予我的，当我因为曹爽的事情而被免职时，可是司马师破格提拔我的。"},{"type":"say","who":"姜维","text":"我不认为你是这样念旧恩的人，这些话可以对外人说，但请不要对我说。我所认知的钟士季，就是如此狼子野心之人。"},{"type":"say","who":"钟会","text":"哈哈哈…我就是在等伯约你这样对我说话，你之前太过恭敬的态度反而让我害怕。"},{"type":"say","who":"钟会","text":"本来以我手上十几万大军，绝对足以和司马昭抗衡，然而底下将领不知道会不会听命于我，让我相当困扰。"},{"type":"say","who":"姜维","text":"所以你把希望寄托在我身上对吧…"},{"type":"say","who":"钟会","text":"没错，你不要把我当傻子，像你这样充满理想的忠义之士，怎么可能会心甘情愿帮我谋反？"},{"type":"say","who":"钟会","text":"你不过是想要利用我和司马昭斗个两败俱伤，最后再收渔翁之利，完成复国的计画而已。"},{"type":"say","who":"姜维","text":"（不好，钟会他真的不是省油的灯，我太小看他了。该怎么办？当场挟持他？还是格杀他？）"},{"type":"say","who":"钟会","text":"伯约，我既然知道你的计画，本来应该当场格杀你，然而我却没做，你知道为什么？"},{"type":"say","who":"钟会","text":"因为你实在是个不可多得的人才，如果没有你，我实在没把握对抗司马昭。"},{"type":"say","who":"钟会","text":"我可以完全支持你的复国计画，在我夺得天下之后，可以把蜀地让出给刘禅，让他复国。"},{"type":"say","who":"钟会","text":"这样应该可以换得你们蜀将的效忠了吧…"},{"type":"say","who":"姜维","text":"为什么会答应我们的请求？"},{"type":"say","who":"钟会","text":"因为我对蜀地没有兴趣，蜀国的魅力在于有一群忠诚过人的蜀将，而非这狭小的土地。"},{"type":"say","who":"钟会","text":"拿这土地换取你们的效忠，实在是非常划算。"},{"type":"say","who":"姜维","text":"既然这样，姜维就誓死协助你完成大业，这也是为了大汉复国的希望。"},{"type":"say","who":"钟会","text":"很好，现在我们就一起前往成都吧，我想卫瓘看见我们，大概会惊讶到连话都说不出来。"},{"type":"say","who":"姜维","text":"（问题在于，钟会还是没有实际要起兵的行动，万一再拖下去，只怕他变卦就麻烦了。）最后的集合剑门关蜀汉军营帐"},{"type":"say","who":"柳隐","text":"老大！当我接到降书的时候，我本来还以为你真的开窍了。最后看来又是空欢喜一场。"},{"type":"say","who":"蒋斌","text":"我大概已经猜到大将军心中真正的想法了…忍辱负重，以求真正的胜利。"},{"type":"say","who":"姜维","text":"不愧是大司马之子，一眼就看出我真正的打算了。"},{"type":"say","who":"王含","text":"既然这样，末将一定跟随大将军到底！"},{"type":"say","who":"柳隐","text":"老大，这种事情千万不能忘记我！"},{"type":"say","who":"姜维","text":"众位的好意，姜维都心领了，但是我不希望每个人都和我一起去成都冒险。"},{"type":"say","who":"姜维","text":"休然，我希望你在这里协助向充和来忠整顿军务，等待成都那边的消息再来起兵响应。"},{"type":"say","who":"柳隐","text":"老大，这太狡猾了！为什么小句可以去，我就不行？"},{"type":"say","who":"姜维","text":"休然你的官阶虽不高，但是和基层士兵相处的时间最久，扣除我以外，你是最能指挥那些军队的。"},{"type":"say","who":"姜维","text":"除了张、廖以及袁将军等因为地位崇高而非去不可外，其他人能不去就不要去。"},{"type":"say","who":"姜维","text":"毕竟此行实在吉凶未卜，不能让太多人去冒这个险。"},{"type":"say","who":"蒋斌","text":"我和钟会有过数面之缘，也有多次书信往来，大将军带我去，一定更可以得到钟会的信任。"},{"type":"say","who":"姜维","text":"可是…你是大司马的儿子…"},{"type":"say","who":"蒋斌","text":"蒋斌一直没有报效国家的机会，今日能得到这个机会，虽死而无憾！"},{"type":"say","who":"姜维","text":"好吧…但是你千万要小心，要是有什么差错，我可没办法向公琰交代。"},{"type":"say","who":"夏侯和","text":"可以借一步说话吗？"},{"type":"say","who":"姜维","text":"我好像过去有看过你的样子。"},{"type":"say","who":"夏侯和","text":"在下夏侯和，字义权，家兄是夏侯仲权，曾经担任过你们的车骑将军。临门一脚剑门关附近"},{"type":"say","who":"夏侯和","text":"名义上我是奉相国命令，前来蜀地安抚百姓，维持治安。"},{"type":"say","who":"夏侯和","text":"实际上我有更重要的任务，那就是把钟会逼反。唯有如此，大魏的中兴才有一线希望。"},{"type":"say","who":"姜维","text":"是谁托付你的任务？曹绫？"},{"type":"say","who":"夏侯和","text":"不，我已经很久没有和公主见面了。其实是我二哥托付我的。"},{"type":"say","who":"姜维","text":"仲权他没死？"},{"type":"say","who":"夏侯和","text":"是的，现在人在洛阳潜伏著。"},{"type":"say","who":"姜维","text":"实在是很感激你告诉我这消息。"},{"type":"say","who":"夏侯和","text":"我听说你和钟会走得很近，才想说你应该可以接触得到他。请问他现在有造反的念头？"},{"type":"say","who":"姜维","text":"有是有，但他始终没有采取实际的行动，我只怕他到时候变卦。"},{"type":"say","who":"夏侯和","text":"既然这样，我会先散布关于相国已经进驻长安的消息，并且把相国的这封信给他。我恐怕邓艾不会就范，所以已经让贾充率领万兵入斜谷，驻汉中乐城，而我自己会率十万大军屯于长安，不久便可相见。"},{"type":"say","who":"姜维","text":"真妙！如果钟会知道司马昭有行动，他一定会被逼反。"},{"type":"say","who":"姜维","text":"（其实司马昭不出兵，钟会不一定会造反，看来是有人说动司马昭采取这样打草惊蛇的动作…该不会是曹绫你吧…）"},{"type":"say","who":"夏侯和","text":"接下来就拜托你了…一定要让钟会造反。"},{"type":"say","who":"姜维","text":"我知道。"},{"type":"say","who":"夏侯和","text":"其实就算钟会造反，能够让大魏中兴或是让你蜀国复国的机会都微乎其微。"},{"type":"say","who":"夏侯和","text":"但是我和二哥都愿意赌上这最后的可能性。"},{"type":"say","who":"姜维","text":"我同意，不能让司马昭这么容易得逞。远大的计画成都郊外魏军营帐"},{"type":"say","who":"钟会","text":"伯约，接下来我想听听看你的意见。"},{"type":"say","who":"姜维","text":"该说的，之前不都已经说了？"},{"type":"say","who":"钟会","text":"事情都到了这个节骨眼，我不希望你还对我有所保留。"},{"type":"say","who":"姜维","text":"你听说了那件事了吗？"},{"type":"say","who":"钟会","text":"我收到相国的亲笔信，看来他是完全不信任我了。"},{"type":"say","who":"钟会","text":"捉拿邓艾，相国明知我能独力办到，如今他率重兵至此，一定是对我起疑。"},{"type":"say","who":"钟会","text":"我们必须立即行动。成则可夺天下，不成还可效法刘备，退保蜀汉之地！现在我已没有任何犹豫，一起共举大业吧！"},{"type":"say","who":"钟会","text":"伯约你可先率五万人为先锋出斜谷，我领大军在后，到长安后兵分两路。"},{"type":"say","who":"钟会","text":"骑兵沿陆路东进，步兵下渭河顺流向东入黄河，估计五日到孟津，可与骑兵会合于洛阳，攻下洛阳则天下可定。"},{"type":"say","who":"姜维","text":"只是如果要起兵，还欠缺一个大义的名分…"},{"type":"say","who":"姜维","text":"以我旧主的名号，足够可以号召大汉的军民起来奋战。但是关于你的远征军…"},{"type":"say","who":"钟会","text":"你是要我放弃他们？"},{"type":"say","who":"姜维","text":"就如同士季你之前说的，那些人恐怕不会听命于你，所以最好早做打算。"},{"type":"say","who":"钟会","text":"不，要是少了大魏军队的战力，要打赢司马昭也不是易事。我想要给他们一个机会。"},{"type":"say","who":"钟会","text":"之前不久听说郭太后已经逝世，我想以她作为大义的名分，伪造她的遗命，试探这些将士的意向。"},{"type":"say","who":"钟会","text":"如果他们同意起兵，那最好。如果不同意，到时候再解决他们也不迟。"},{"type":"say","who":"姜维","text":"（看来钟会终于下定决心要造反了，接下来只要想办法让钟会杀光那些魏将，最后钟会就只能依赖我们了。）杜预的应变涪县魏军营帐"},{"type":"say","who":"荀恺","text":"杜长史，事情真的有些古怪…"},{"type":"say","who":"杜预","text":"看来护军也发现问题了。"},{"type":"say","who":"杜预","text":"明明邓艾已经被逮捕，为什么还要把军队开到成都附近，加上今天这个要我把粮草运到成都的命令…"},{"type":"say","who":"荀恺","text":"就我私下派人去打听，司徒（钟会）确实要把军队开进成都没有错。"},{"type":"say","who":"杜预","text":"为什么好端端要把军队开进成都？明明邓艾就已经不在了。"},{"type":"say","who":"杜预","text":"等一下…事情不好了！"},{"type":"say","who":"荀恺","text":"怎么样？"},{"type":"say","who":"杜预","text":"多亏护军你细心，要不然就要酿成大祸。"},{"type":"say","who":"杜预","text":"现在就推说道路崎岖，粮食运送不易，请他多等待些时日。"},{"type":"say","who":"荀恺","text":"我明白了，看来你也认为钟会有问题？"},{"type":"say","who":"杜预","text":"对，这也是他为什么要把我留在这里的理由。"},{"type":"say","who":"杜预","text":"现在我们手上有粮草当资本，就算钟会真的起兵造反，我们只要烧掉这些粮草，至少可以降低他一大半的战斗力。"},{"type":"say","who":"荀恺","text":"看来灭蜀不过只是开始而已…"},{"type":"say","who":"杜预","text":"没错，在这场即将到来的腥风血雨中，不知道我们能不能活下去呢？郭太后遗命成都皇宫"},{"type":"say","who":"钟会","text":"知道我邀请诸位前来有什么目的吗？"},{"type":"say","who":"卫瓘","text":"（这钟会一定有问题，本来我已经搞定邓艾，没想到这家伙居然带著大队人马冲进成都，摆明就是占领嘛。）"},{"type":"say","who":"卫瓘","text":"（若不是陇西军都还不肯听命，我早就带著这些人和你拚了。）"},{"type":"say","who":"钟会","text":"我这里有个郭太后在临终前托付给我的遗命，现在就给大家过目。"},{"type":"say","who":"钟会","text":"太后命我统帅伐蜀兵马，即刻起命讨伐弑君逆贼司马昭。"},{"type":"say","who":"钟会","text":"钟会虽然不才，但也是忠义著称的颖川钟家之后，因此只有奉诏讨伐司马昭，才能对得起先父的名声。"},{"type":"say","who":"钟会","text":"现在愿意响应我起兵的，就在这檄文上签下自己的名字！"},{"type":"say","who":"卫瓘","text":"（糟糕了…）"},{"type":"say","who":"胡烈","text":"（钟会果然要造反…）"},{"type":"say","who":"羊琇","text":"（该怎么办？）"},{"type":"say","who":"夏侯和","text":"（眼前这些都是司马家的亲戚或是受司马家提拔的人，留著只会坏事。看来是我发挥的时候了。）"},{"type":"say","who":"夏侯和","text":"（如果可以用我卑微的生命来换取大事的成功，那又何乐而不为？）"},{"type":"say","who":"夏侯和","text":"哈哈哈，我就知道钟会你这逆贼要造反！"},{"type":"say","who":"夏侯和","text":"太后去世的时候，我人也在洛阳。据我所知，太后病逝之前可从来没见过任何人，这篇遗诏不知从何人手上所得？"},{"type":"say","who":"钟会","text":"我自然有我的管道。"},{"type":"say","who":"夏侯和","text":"呵呵呵，我看你的遗诏，来源大概和毌丘俭的密诏一样吧！"},{"type":"say","who":"胡烈","text":"这种有问题的遗诏，恕我们不能遵从！"},{"type":"say","who":"羊琇","text":"很抱歉，我也不能签！"},{"type":"say","who":"羊琇","text":"（干！其实我怕得要死，都被那个夏侯和搞得非和钟会对干不可。）"},{"type":"say","who":"钟会","text":"哼！你们这些司马昭的走狗，我可是一点也不意外！"},{"type":"say","who":"卫瓘","text":"等一下，我倒是认为这篇遗诏可以好好研究一下，等确定真伪之后再做定夺。"},{"type":"say","who":"卫瓘","text":"如果确定是真的，到时候再响应也不迟。"},{"type":"say","who":"夏侯和","text":"去你的！你这胆小鬼！"},{"type":"say","who":"胡烈","text":"没出息的东西！"},{"type":"say","who":"钟会","text":"（如果把监军卫瓘给关了，到时候恐怕就让司马昭有借口直接攻击蜀地了。）"},{"type":"say","who":"钟会","text":"（现在我粮草未齐，还没有把握能打赢司马昭，不如先放他一马吧。）"},{"type":"say","who":"钟会","text":"把除了监军卫伯玉外的人全部都给我关到朝堂里去，紧闭城门宫门，严兵看守。姜维密函成都刘禅住处"},{"type":"say","who":"郤正","text":"陛下…"},{"type":"say","who":"刘禅","text":"像你这样有才干又对朕忠心耿耿的人，为什么朕不能早点认识你？"},{"type":"say","who":"郤正","text":"一切都没有太晚，请陛下看看大将军给您的信。请陛下忍耐数天的耻辱，我要让社稷恢复安定、日月恢复光明。"},{"type":"say","who":"刘禅","text":"这个姜维还是这么傻…他这样做，恐怕会让成都血流成河吧。"},{"type":"say","who":"郤正","text":"陛下，大将军也是一片忠诚…就算背负所有罪恶，他也不放弃那最后一丝机会。"},{"type":"say","who":"刘禅","text":"朕知道，朕也没有怪他的意思。"},{"type":"say","who":"刘禅","text":"其实朕的本意，是想让朕自己一个人扛起亡国的罪名就够了。没想到大将军他居然也要让自己背负这样的臭名。"},{"type":"say","who":"刘禅","text":"万一失败，恐怕后人对他的评价，只会有嘲笑和谩骂而已。"},{"type":"say","who":"郤正","text":"不会的，因为臣一定会想办法让后世知道，大将军其实是什么样的人。"},{"type":"say","who":"刘禅","text":"说得也是，你就想办法让真相传达给后世吧。锦囊妙计成都魏将软禁处"},{"type":"say","who":"胡烈","text":"没想到钟会这么大意，居然让我们关在一起。"},{"type":"say","who":"羊琇","text":"我想他是单纯认为我们这群笨蛋，就算想破头也想不出什么好办法。"},{"type":"say","who":"胡烈","text":"说得也是…现在和外界断绝联系，我们在这里怎么死的都不知道。"},{"type":"say","who":"羊琇","text":"等一下…我虽然笨，但娘可不笨…这里有个娘交给我的锦囊，说危急时候可以打开来看。"},{"type":"say","who":"羊琇","text":"我看看…卫瓘和丘建…"},{"type":"say","who":"羊琇","text":"卫瓘那奸诈的老小子我知道，但是丘建…"},{"type":"say","who":"胡烈","text":"没想到令堂居然如此厉害，我想她应该只有在洛阳看过那个人一次而已。"},{"type":"say","who":"胡烈","text":"丘建本来是我的左右，后来我把他推荐给相国，钟会又向相国请求把他带在身边，钟会似乎对他相当信任。"},{"type":"say","who":"羊琇","text":"娘还真可怕，居然会注意到这个细微的事情。"},{"type":"say","who":"胡烈","text":"没错，如果透过丘建，我们就有重见天日的机会。展开行动成都姜维住处"},{"type":"say","who":"姜维","text":"钟会对于杀贼将的事情还在迟疑，再继续拖下去，对我们会很不利。"},{"type":"say","who":"廖化","text":"那么我们干脆自己动手如何？"},{"type":"say","who":"姜维","text":"不可，这样做除了会让钟会不信任我们之外，更会因此和贼军结仇，陷我们于不利的处境。"},{"type":"say","who":"蒋显","text":"大将军，您的想法我固然知道，但是也请您不要太顾忌我们的性命。"},{"type":"say","who":"蒋显","text":"要知道，进行这样的复国计画怎么能不付出牺牲？大哥、我、甚至在场的每个人都是抱著同样想法。"},{"type":"say","who":"姜维","text":"实在是对你们感到很抱歉…"},{"type":"say","who":"句扶","text":"这是什么话，我们相处已经多久了，还如此见外？"},{"type":"say","who":"袁綝","text":"义父把一切都托付给我，我自然要为义父想要守护的的大汉奋战到最后一刻。"},{"type":"say","who":"宁随","text":"这是为了大汉的最后一搏，就算失败也可以挺起胸膛去见丞相。"},{"type":"say","who":"姜维","text":"那么大家就和我一起去见钟会吧，这次一定要说服他坑杀所有贼将才行。丘建的建议成都皇宫"},{"type":"say","who":"丘建","text":"听说司徒您把所有的高阶将领都软禁起来，是否有这样的事情？"},{"type":"say","who":"钟会","text":"确有其事。"},{"type":"say","who":"丘建","text":"那么司徒日后起义之时，要靠何人来统领这些部队？"},{"type":"say","who":"钟会","text":"那些司马家的走狗，不值得信赖，杀光也无妨。我打算让姜维为首的蜀将来领兵。"},{"type":"say","who":"丘建","text":"如此…司徒您就危险了…"},{"type":"say","who":"钟会","text":"什么？！"},{"type":"say","who":"丘建","text":"莫非您还真的相信那些蜀人？他们投降不过是一时的权宜之计，随时抱著复国之念，准备咬您一口。"},{"type":"say","who":"钟会","text":"这点不用担心，我已经答应让他们复国，我们之间并无利害冲突。"},{"type":"say","who":"丘建","text":"错了！我们对那些蜀人来说，总归还是外人，要真正完成复国，就得排除我们。"},{"type":"say","who":"丘建","text":"试问若是您杀光所有我军将领，身边都是蜀将，还有谁可以阻止他们对您不利？"},{"type":"say","who":"钟会","text":"（这倒是…我一时之间冲昏头，似乎又太过信任姜维了。）"},{"type":"say","who":"丘建","text":"其实我们一路走来，都是靠这些人才可以取汉中、破阳安，他们才是真正可以倚靠的人。"},{"type":"say","who":"钟会","text":"可是他们摆出不合作的态度，让人困扰。"},{"type":"say","who":"丘建","text":"经过几天的挨饿受冻，这些人几乎都是有心无力了。"},{"type":"say","who":"钟会","text":"这些人难道不知道，只要在檄文上签名就可以重获自由？"},{"type":"say","who":"丘建","text":"话可不是这样说的，现在这样硬逼，只会让某些人态度变得更强硬，弄得两败俱伤。"},{"type":"say","who":"丘建","text":"小人建议，让各部允许一人亲兵送来食物和御寒衣物，如此这些将领得到温饱，到时必会感谢司徒您的恩义。"},{"type":"say","who":"钟会","text":"只是我担心宫中之事宣扬出去，到时必定会造成极大混乱。"},{"type":"say","who":"丘建","text":"请不用担心，小人绝对不会让这些亲兵进入宫中，只让他们把东西丢下就走。"},{"type":"say","who":"钟会","text":"好，就照你的意思去做。到时候若能说服这些将领，起兵成功之日必定会让你成为三公。"},{"type":"say","who":"丘建","text":"多谢司徒…不，圣上的抬爱。"},{"type":"say","who":"钟会","text":"圣上？哈哈哈哈哈…"},{"type":"say","who":"丘建","text":"（钟会你这王八蛋，你一世聪明，看来是要在这时候老马了。）事机败露成都魏将软禁处士兵将军，我还以为此生看不到您了…"},{"type":"say","who":"胡烈","text":"安静一点，光凭你一个人是没办法救出我们所有人。"},{"type":"say","who":"胡烈","text":"所以我要请你带话给我儿子，让他来救我。"},{"type":"say","who":"胡烈","text":"就说丘建偷偷告诉我，钟会已经做了一个大坑，白棒数千条，想要把外面的士兵都叫进来。"},{"type":"say","who":"胡烈","text":"每人赐一顶白帽子，拜为散将，再依次把我们都用棒子打死，尸体丢入坑里。"},{"type":"say","who":"羊琇","text":"（真是有点吹牛不打草稿，不过只有这样才可以激起士兵们的怒火吧。）士兵是！小人一定把话带到。胡渊举兵成都曹魏军帐外"},{"type":"say","who":"胡渊","text":"我爹的亲兵把这样的消息带过来，愿意去铲除逆贼钟会的就跟著我来。"},{"type":"say","who":"皇甫闿","text":"等一下，你怎么知道这消息是真是假？"},{"type":"say","who":"胡渊","text":"是那个亲兵亲眼看见的，而且各位不怀疑我军的高阶将领为什么都失踪了？"},{"type":"say","who":"庞会","text":"事情确实不单纯（眉头一皱）。"},{"type":"say","who":"李辅","text":"问题是，似乎不该你来发号施令吧，你算什么东西？"},{"type":"say","who":"胡渊","text":"现在不是计较官位大小的时候了吧！"},{"type":"say","who":"句安","text":"我有个疑虑…"},{"type":"say","who":"胡渊","text":"快说，我可是不信任你这个叛将，要是有什么不轨的举动，我第一个杀你！"},{"type":"say","who":"句安","text":"现在卫监军人还在成都官署内，如果我们贸然起兵，恐怕会危及到他的性命，到时我们纵然平乱有功也没用了。"},{"type":"say","who":"句安","text":"更何况，我们这些将领品秩都太低，根本没有权力调动部队。如果能得到卫监军的协助，事情就大不相同。"},{"type":"say","who":"胡渊","text":"说得倒是很有道理。"},{"type":"say","who":"蒋舒","text":"我也有话要说…"},{"type":"say","who":"胡渊","text":"说吧，叛将二号！"},{"type":"say","who":"蒋舒","text":"我对成都的地理位置非常熟悉，如果诸位相信我的话，请让我去营救卫监军！"},{"type":"say","who":"李辅","text":"这个人可靠吗？"},{"type":"say","who":"王韬","text":"你这个前孟达部将还敢说这种话？"},{"type":"say","who":"李辅","text":"你少用这种口气和我说话，我好歹是个前将军！"},{"type":"say","who":"庞会","text":"不妨让他试试看吧，在座各位恐怕也没人有这个本事自由进出成都不是吗？"},{"type":"say","who":"庞会","text":"（看来，该舍弃钟会的时候到了，只有跟著这些人起兵，才有机会趁乱杀光关羽全家。）卫瓘脱身成都皇宫"},{"type":"say","who":"钟会","text":"现在城外似乎有些士兵因为听信谣言而骚动，希望你能够出城安抚他们。"},{"type":"say","who":"钟会","text":"（这该死的丘建，我居然忘记他曾经是胡烈心腹，没想到在这重要关头出事。）"},{"type":"say","who":"卫瓘","text":"您是他们的统帅，为什么要我去呢？应该要自己去才对吧。"},{"type":"say","who":"卫瓘","text":"（其实这是脱身的大好机会，如果我表现得太干脆，恐怕你打死也不会放我去。）"},{"type":"say","who":"钟会","text":"你是监军，应该先让你去，我随后再跟著去。"},{"type":"say","who":"卫瓘","text":"好吧…既然您也肯去，我就勉为其难出发吧。"},{"type":"say","who":"钟会","text":"等一下…万一卫瓘出城后反咬我一口，号令外面的军队进城就糟了！"},{"type":"say","who":"钟会","text":"来人！快点去追卫监军回来！"},{"type":"say","who":"钟会","text":"（该死，怎么最近我一直出现失误，我这今之张良怎么了？）诈病避祸成都城外官署"},{"type":"say","who":"武官","text":"监军，司徒请您回去成都一趟。"},{"type":"say","who":"卫瓘","text":"………"},{"type":"say","who":"武官","text":"怎么忽然病成这样？"},{"type":"say","who":"蒋舒","text":"监军身体本来就不好，刚才回到官署时忽然大吐，现在连话都说不出来了。"},{"type":"say","who":"武官","text":"我们司徒早就知道会这么巧，所以特别请了名医来诊断。"},{"type":"say","who":"蒋舒","text":"（糟了…）"},{"type":"say","who":"医生","text":"这脉象…四平八稳，很正常呀！没有问题啊！"},{"type":"say","who":"医生","text":"等一下…怪怪的…"},{"type":"say","who":"武官","text":"怎么啦？"},{"type":"say","who":"医生","text":"我从来没听过这么乱的脉象。"},{"type":"say","who":"蒋舒","text":"监军还有救吗？"},{"type":"say","who":"医生","text":"试试看。"},{"type":"say","who":"医生","text":"这怎么回事？！"},{"type":"say","who":"武官","text":"你听到什么？"},{"type":"say","who":"医生","text":"武皇帝的《短歌行》…"},{"type":"say","who":"武官","text":"什么？！"},{"type":"say","who":"医生","text":"我看还是赶快准备后事吧！监军，我先告辞了！"},{"type":"say","who":"武官","text":"为了个半死人浪费那么多的时间！我们走！"},{"type":"say","who":"蒋舒","text":"大夫，快救救监军…"},{"type":"say","who":"卫瓘","text":"若不是我会改变自己脉象的方法，加上喝一堆盐水喝到吐，恐怕是难逃此劫。"},{"type":"say","who":"卫瓘","text":"不过我还是要感谢你在中途接我，让我能躲过钟会的手下，平安回到城外官署。"},{"type":"say","who":"蒋舒","text":"在下蒋舒，在阳安关时我们有一面之缘。"},{"type":"say","who":"卫瓘","text":"我知道…今日你前来，应该是为了钟会谋反之事吧。"},{"type":"say","who":"蒋舒","text":"是的，钟会囚禁大量高阶将领，城外将士知道消息后，迫不及待想要攻进成都。"},{"type":"say","who":"蒋舒","text":"然而城外将士虽多，却无一高阶将领可以指挥，军令不行，想平乱也有心无力。"},{"type":"say","who":"卫瓘","text":"你还不错嘛，想到找上我来指挥全局。看来你并非只是个见风转舵的小人。"},{"type":"say","who":"卫瓘","text":"这里是符节和盖有我官印的亲笔书信，如此要讨伐钟会就不是难事了。"},{"type":"say","who":"蒋舒","text":"多谢大人！公元二六四年元月，卫瓘的军令传遍城外魏军所有营房，所有魏军士兵，在胡渊的率领之下，开始攻向成都。决死之战成都姜维住处"},{"type":"say","who":"张翼","text":"大事不妙了！现在城外贼军开始攻进城内，似乎是消息走漏出去！"},{"type":"say","who":"姜维","text":"想不到…最后还是失败了…莫非是天意？"},{"type":"say","who":"句扶","text":"不，事情还没有结束！我们还可以和贼军拚了！"},{"type":"say","who":"蒋斌","text":"没错！就算死，也要多带几个贼军一起死！"},{"type":"say","who":"袁綝","text":"在这里光荣战死也是不错的结局，到那边就算面对义父也抬头挺胸了。"},{"type":"say","who":"姜维","text":"那么…我们就来个知其不可为而为的奋斗吧…"},{"type":"say","who":"姜维","text":"孝兴，你和幼常趁现在敌人包围网没有构成之际，想办法脱身前往我军阵地。"},{"type":"say","who":"姜维","text":"只要敌人人数不多，光靠我们从剑门关带来的五千精兵应该足以克敌。"},{"type":"say","who":"姜维","text":"元俭，你和太仆前往陛下寝宫，保护陛下安全。"},{"type":"say","who":"廖化","text":"伯约，你要保重！"},{"type":"say","who":"蒋显","text":"蒋显一定用生命保护陛下安全！"},{"type":"say","who":"姜维","text":"剩下的人，就随我来吧…"},{"type":"say","who":"句扶","text":"不公平！我想要和张翼交换！"},{"type":"say","who":"姜维","text":"任务已经排定，不要再争执了！"},{"type":"say","who":"张翼","text":"没想到伯约最后会选中我和你一起作战，你愿意相信我，我真的很高兴。"},{"type":"say","who":"蒋斌","text":"能够和大将军奋战到最后一刻，蒋斌纵死也无憾。"},{"type":"say","who":"袁綝","text":"能够参加战斗到最后一刻，真的感到很光荣。"},{"type":"say","who":"姜维","text":"说什么傻话，我们可要支撑到孝兴的援军赶到，千万不能轻易言死。"},{"type":"say","who":"姜维","text":"（丞相，恕姜维无能，现在只有一死来报答您的知遇之恩了。）"},{"type":"say","who":"姜维","text":"（香，现在已经超过四十年了，这下你应该会欢迎我了吧。）第一次的抗命成都郊外"},{"type":"say","who":"杨兰","text":"情况怎么会变得这么糟糕，本来只是想偷跑回来看一下姜维怎么样，却发生这样的事。"},{"type":"say","who":"诸葛果","text":"早在一开始，主公或许就知道事情会变成这样，所以才不让我们跟随。"},{"type":"say","who":"杨兰","text":"开什么玩笑！我才不会让姜维这样死掉！"},{"type":"say","who":"诸葛果","text":"这也是果第一次违抗主公的命令…"},{"type":"say","who":"杨兰","text":"要进去成都还不算难，因为现在包围还没有完全完成。"},{"type":"say","who":"杨兰","text":"只是我们就算救出姜维等人，恐怕也逃不远吧。"},{"type":"say","who":"诸葛果","text":"不用担心，成都西山那边是五斗米道的地盘，教主范长生拥众十万以上，他已经答应收容我们了。"},{"type":"say","who":"诸葛果","text":"只要能够逃到成都西山的地界，没有一兵一卒可以追进来。"},{"type":"say","who":"杨兰","text":"好！我们快点进去成都吧！"},{"type":"say","who":"杨兰","text":"（面对这些乱军，恐怕连逃到成都西山都是问题。看来…只有用这一招了…）友情成都"},{"type":"say","who":"姜维","text":"两位将军可以先进去宫内，我还有些话想和袁将军说。"},{"type":"say","who":"张翼","text":"好，那么我们就先在宫中等你。"},{"type":"say","who":"姜维","text":"其实我一直想要找借口让显通你不用跟着一起死，然而却还是失败了。"},{"type":"say","who":"袁綝","text":"剩下的三个人，每个人都顽固得跟石头一样，就算是苏秦张仪再生也说不动。"},{"type":"say","who":"姜维","text":"不过可以的话，我希望显通你能活下去。"},{"type":"say","who":"袁綝","text":"别说笑了，义父当年希望我代替他守护大汉，结果大汉却灭亡，我哪有脸还能苟活在世上。"},{"type":"say","who":"姜维","text":"可是…有件事情你似乎忽略了，你有著汝南袁家的血统。"},{"type":"say","who":"姜维","text":"就我所知，袁公路的血脉还在江东残存，但袁本初的血脉却剩你一个人而已。"},{"type":"say","who":"姜维","text":"要是你死了，袁本初这位一代英豪将从此绝后。"},{"type":"say","who":"袁綝","text":"我说过很多次，袁绍那个人我连面都没见过，对他根本没有感情。"},{"type":"say","who":"姜维","text":"陈将军在当初临行前，有告诉我一件事。"},{"type":"say","who":"袁綝","text":"义父他见过你？唉，亏我还想瞒着你。"},{"type":"say","who":"姜维","text":"当年他比谁都恨袁绍，因为袁绍亲手杀了一位他最重要的人。"},{"type":"say","who":"姜维","text":"他将你从满宠手上救出，为的其实是要手刃袁绍的儿子。"},{"type":"say","who":"袁綝","text":"那么义父为什么不下手？"},{"type":"say","who":"姜维","text":"因为他看了袁绍写的这封信，而那封信现在就在我手上。"},{"type":"say","who":"姜维","text":"陈将军说在适当的时机再交给你，只可惜之后我们可能没机会见面了，所以现在先给你。"},{"type":"say","who":"袁綝","text":"现在给我这信也不会改变我的主意，我已经立誓要和大汉共存亡了。"},{"type":"say","who":"姜维","text":"既然这样…成都西门的把守工作就交给你了，别让人从后面进来。"},{"type":"say","who":"袁綝","text":"真困难的要求，我尽力而为了。"},{"type":"say","who":"姜维","text":"永别了，显通。"},{"type":"say","who":"袁綝","text":"可以的话，我还真不希望最后在我身边的"},{"type":"say","who":"旁白","text":"▶ 是你…"},{"type":"say","who":"袁綝","text":"（只可惜她眼中永远只有姜维，如果我战死在这里，也许她也能为我流一滴眼泪吧。）终焉镇魂曲成都皇宫"},{"type":"say","who":"钟会","text":"我正要找伯约你，有士兵像是要来为非作歹，我应当跟他们说什么？"},{"type":"say","who":"姜维","text":"（现在钟会已经慌乱得六神无主，和平常的他可以说是判若两人，看来他离死期已经不远了。）"},{"type":"say","who":"姜维","text":"（之前他算无遗漏，原因在于担任别人的副手。现在要算到自己的事，关系到生死大事，自然错误百出。）"},{"type":"say","who":"姜维","text":"只有迎击一途！现在贼军绝对是要去营救那些被囚禁的将领，你该知道要怎么做。"},{"type":"say","who":"钟会","text":"杀光那些将领，然后再和贼兵正面对决！"},{"type":"say","who":"姜维","text":"我已经派人去城外带前汉军部队回来支援，只要能撑住一时半刻，还是有机会的。"},{"type":"say","who":"钟会","text":"那就好！准备迎击！"},{"type":"say","who":"姜维","text":"（无论孝兴他们动作多快，援军是铁定赶不上的。若不是为了取信于钟会，我也不希望伯恭和蒋斌陪我一起死。）"},{"type":"say","who":"姜维","text":"（我姜维加入大汉将近四十年，现在就用这一战来画下句点。）產ち传"},{"type":"say","who":"姜维","text":"（最后一战，死也要死得轰轰烈烈！）產ち传"},{"type":"say","who":"钟会","text":"还有机会的…我的皇帝梦…绝对还是有机会的…"},{"type":"say","who":"姜维","text":"（没有机会了…永远也没有了，难道这点你还是不明白？）產ち传"},{"type":"say","who":"张翼","text":"真是愉快，或许我是现在全大汉最幸福的人吧。"},{"type":"say","who":"姜维","text":"伯恭…"},{"type":"say","who":"张翼","text":"伯约，我要为我过去对你的不礼貌道歉。"},{"type":"say","who":"张翼","text":"如果我早点知道你是这样忠勇爱国，甚至连自己名誉都不在乎的人，相信应该早就能成为好友。"},{"type":"say","who":"张翼","text":"其实你爱大汉的心，就和我爱益州的心其实是相同的，要是能早点理解这点就好了。"},{"type":"say","who":"姜维","text":"现在成为好友还不迟，至少我们现在终于可以互相了解了。"},{"type":"say","who":"张翼","text":"是呀，就算是死，也死得没有牵挂。產ち传"},{"type":"say","who":"钟会","text":"真恨不能和蒋护军多相处一段时间。"},{"type":"say","who":"蒋斌","text":"司徒大人的才学和书法，蒋斌才是钦佩不已，真想和您多讨教一番。"},{"type":"say","who":"蒋斌","text":"（只可惜你的为人让我鄙视…）"},{"type":"battle","index":0}]},"battles":[{"index":0,"width":16,"height":10,"objective":"全灭敌军","grid":["ffffffffffffffff","ffffffffffffffff","ffppppppppppppff","fppppppppppppppf","fpwwwpppppwwwppf","fpwwpppppppwwppf","fpwwwpppppwwwppf","fppppppppppppppf","ffppppppppppppff","ffffffffffffffff"],"units":[{"def":{"name":"姜维","class":"commander","level":8,"skills":["fireball","heal","inspire"],"weapon":"sword","leader":true},"x":3,"y":4,"faction":"ally"},{"def":{"name":"赵云","class":"hero","level":9,"skills":["charge"],"weapon":"hualiu"},"x":4,"y":5,"faction":"ally"},{"def":{"name":"王平","class":"infantry","level":7,"skills":[],"weapon":"sword"},"x":3,"y":6,"faction":"ally"},{"def":{"name":"马岱","class":"dragoon","level":7,"skills":["charge"],"weapon":"halberd"},"x":5,"y":5,"faction":"ally"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":3,"faction":"enemy"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":7,"faction":"enemy"},{"def":{"name":"枪兵","class":"spearman","level":5,"skills":[],"weapon":"spear"},"x":10,"y":5,"faction":"enemy"},{"def":{"name":"弓兵","class":"archer","level":5,"skills":[],"weapon":"bow"},"x":13,"y":4,"faction":"enemy"}]}]});
})();
